354	// --- HTTP
355	
356	/// One request as it came off the socket, with what the frame needs
357	/// and nothing it does not: the bearer token is taken out of the
358	/// headers so it is never logged with them.
359	#[derive(Debug, Clone, PartialEq, Eq)]
360	pub struct RemoteRequest {
361	    pub method: String,
362	    /// The path without its query string.
363	    pub path: String,
364	    /// The query string's pairs, undecoded: ids and numbers only.
365	    pub query: Vec<(String, String)>,
366	    pub body: Vec<u8>,
367	    /// The `Authorization: Bearer` value, if any.
368	    pub bearer: Option<String>,
369	    /// The `Sec-WebSocket-Key` of a request that asks to upgrade to a
370	    /// WebSocket; the frame answers [`SUBSCRIBED`] to accept it.
371	    pub upgrade: Option<String>,
372	}
373	
374	impl RemoteRequest {
375	    /// The first value of a query parameter.
376	    #[must_use]
377	    pub fn param(&self, name: &str) -> Option<&str> {
378	        self.query
379	            .iter()
380	            .find(|(n, _)| n == name)
381	            .map(|(_, v)| v.as_str())
382	    }
383	}
384	
385	/// What the frame answers: a status and a JSON body, and whether the
386	/// request was made by a paired device, which moves the connection
387	/// from the unauthenticated pool to the paired one.
388	#[derive(Debug, Clone, PartialEq, Eq)]
389	pub struct RemoteReply {
390	    pub status: u16,
391	    pub body: Vec<u8>,
392	    pub authenticated: bool,
393	}
394	
395	/// One request off a connection, with the channel its reply goes back
396	/// on and, for an upgrade request, the queue the connection will feed
397	/// its WebSocket from once the frame accepts.
398	pub struct RemoteIncoming {
399	    pub request: RemoteRequest,
400	    pub reply: SyncSender<RemoteReply>,
401	    pub subscriber: Option<SubscriberQueue>,
402	}
403	
404	/// The status the frame answers an upgrade request with to accept it;
405	/// the connection thread then writes the 101 and becomes a subscriber.
406	pub const SUBSCRIBED: u16 = 101;
407	
408	/// How many events a subscriber may fall behind before it is dropped.
409	pub const SUBSCRIBER_QUEUE: usize = 256;
410	
411	/// How long a subscriber's thread waits for an event before it looks
412	/// for a frame from the device (a close, a ping, a `watch`).
413	const SUBSCRIBER_POLL: Duration = Duration::from_millis(50);
414	
415	/// The frame's end of a subscriber: events go in as JSON text; a full
416	/// queue drops the sender with `overflow` set, which the connection
417	/// thread turns into `resync_required` and a close. `id` names the
418	/// subscriber in the frames it sends back.
419	pub struct SubscriberQueue {
420	    pub id: u64,
421	    pub tx: SyncSender<String>,
422	    pub overflow: Arc<AtomicBool>,
423	}
424	
425	/// A text frame a subscribed device sent (`watch`, `unwatch`), or
426	/// `None` once its socket ended, however it ended.
427	pub struct SubscriberFrame {
428	    pub subscriber: u64,
429	    pub text: Option<String>,
430	}
431	
432	/// How many device frames may wait for the frame thread.
433	const FRAMES: usize = 64;
434	
435	/// The most a request line and its headers may take, and the most a
436	/// body may be.
437	pub const MAX_HEAD: usize = 8 * 1024;
438	pub const MAX_BODY: usize = 64 * 1024;
439	
440	/// The head of one HTTP/1.1 request: method, target, lowercased
441	/// headers, body. `None` at a clean end of stream before any byte; an
442	/// oversized or malformed request is an error that closes the
443	/// connection.
444	fn read_request<R: Read>(reader: &mut BufReader<R>) -> io::Result<Option<RemoteRequest>> {
445	    let mut line = String::new();
446	    if reader.read_line(&mut line)? == 0 {
447	        return Ok(None);
448	    }
449	    let mut parts = line.split_whitespace();
450	    let (Some(method), Some(target)) = (parts.next(), parts.next()) else {
451	        return Err(io::Error::new(
452	            io::ErrorKind::InvalidData,
453	            "bad request line",
454	        ));
455	    };
456	    let mut headers: Vec<(String, String)> = Vec::new();
457	    let mut total = line.len();
458	    loop {
459	        let mut h = String::new();
460	        if reader.read_line(&mut h)? == 0 {
461	            return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "headers cut"));
462	        }
463	        total += h.len();
464	        if total > MAX_HEAD {
465	            return Err(io::Error::new(io::ErrorKind::InvalidData, "head too large"));
466	        }
467	        let h = h.trim_end();
468	        if h.is_empty() {
469	            break;
470	        }
471	        if let Some((n, v)) = h.split_once(':') {
472	            headers.push((n.trim().to_ascii_lowercase(), v.trim().to_owned()));
473	        }
474	    }
475	    let header = |name: &str| {
476	        headers
477	            .iter()
478	            .find(|(n, _)| n == name)
479	            .map(|(_, v)| v.as_str())
480	    };
481	    let length: usize = header("content-length")
482	        .and_then(|v| v.parse().ok())
483	        .unwrap_or(0);
484	    if length > MAX_BODY {
485	        return Err(io::Error::new(io::ErrorKind::InvalidData, "body too large"));
486	    }
487	    let bearer = header("authorization")
488	        .and_then(|v| v.strip_prefix("Bearer "))
489	        .map(|t| t.trim().to_owned())
490	        .filter(|t| !t.is_empty());
491	    let upgrade = header("upgrade")
492	        .filter(|u| u.eq_ignore_ascii_case("websocket"))
493	        .and_then(|_| header("sec-websocket-key"))
494	        .map(str::to_owned);
495	    let (path, query) = target.split_once('?').unwrap_or((target, ""));
496	    let query = query
497	        .split('&')
498	        .filter(|s| !s.is_empty())
499	        .map(|pair| {
500	            let (n, v) = pair.split_once('=').unwrap_or((pair, ""));
501	            (n.to_owned(), v.to_owned())
502	        })
503	        .collect();
504	    let mut body = vec![0; length];
505	    reader.read_exact(&mut body)?;
506	    Ok(Some(RemoteRequest {
507	        method: method.to_owned(),
508	        path: path.to_owned(),
509	        query,
510	        body,
511	        bearer,
512	        upgrade,
513	    }))
514	}
