516	/// The 101 that switches a connection to WebSocket. The request was
517	/// already read by `read_request`, so `tungstenite::accept` cannot be
518	/// used; the stream is wrapped with `from_raw_socket` after this.
519	fn respond_upgrade<W: Write>(w: &mut W, key: &str) -> io::Result<()> {
520	    write!(
521	        w,
522	        "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {}\r\n\r\n",
523	        tungstenite::handshake::derive_accept_key(key.as_bytes())
524	    )?;
525	    w.flush()
526	}
527	
528	/// Write one response. Head and body in one write, so a reply is one
529	/// TLS record and one segment.
530	fn respond<W: Write>(w: &mut W, status: u16, body: &[u8]) -> io::Result<()> {
531	    let reason = match status {
532	        200 => "OK",
533	        400 => "Bad Request",
534	        401 => "Unauthorized",
535	        403 => "Forbidden",
536	        404 => "Not Found",
537	        405 => "Method Not Allowed",
538	        413 => "Content Too Large",
539	        429 => "Too Many Requests",
540	        503 => "Service Unavailable",
541	        504 => "Gateway Timeout",
542	        _ => "Error",
543	    };
544	    let mut out = format!(
545	        "HTTP/1.1 {status} {reason}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: keep-alive\r\n\r\n",
546	        body.len()
547	    )
548	    .into_bytes();
549	    out.extend_from_slice(body);
550	    w.write_all(&out)?;
551	    w.flush()
552	}
