554	/// The error body the connection thread sends for what never reaches
555	/// the frame.
556	fn error_body(code: &str, message: &str) -> Vec<u8> {
557	    serde_json::json!({ "error": { "code": code, "message": message } })
558	        .to_string()
559	        .into_bytes()
560	}
