564	/// At most 16 connections, 4 of them unauthenticated. The 4 are a pool
565	/// of their own: a flood of strangers fills its own slots and never a
566	/// paired device's.
567	pub const MAX_UNAUTHENTICATED: usize = 4;
568	pub const MAX_PAIRED: usize = 12;
569	/// The TLS handshake and the first request line within this.
570	const HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(5);
571	/// A paired device polling on a kept connection may sit idle this long
572	/// between requests.
573	const IDLE_TIMEOUT: Duration = Duration::from_secs(30);
574	const WRITE_TIMEOUT: Duration = Duration::from_secs(10);
575	/// How long a connection waits for the frame's answer. The frame
576	/// answers on its next pass, so this only matters if it has stalled.
577	pub(crate) const ANSWER_TIMEOUT: Duration = Duration::from_secs(60);
578	/// The frame drains at most this many requests per pass from a channel
579	/// this deep; a full channel answers 503 without reaching the frame.
580	pub const DRAIN_PER_PASS: usize = 8;
581	const INBOX: usize = 64;
582	/// `/pair` and `/info` per minute per listener, answered 429 past it.
583	const PAIR_PER_MINUTE: usize = 6;
584	const INFO_PER_MINUTE: usize = 60;
