589	#[derive(Default)]
590	struct Pools {
591	    unauthenticated: AtomicUsize,
592	    paired: AtomicUsize,
593	}
594	
595	/// Allows `max` events per `per`, counted on a sliding window.
596	struct RateWindow {
597	    stamps: VecDeque<Instant>,
598	    max: usize,
599	    per: Duration,
600	}
601	
602	impl RateWindow {
603	    fn new(max: usize, per: Duration) -> Self {
604	        Self {
605	            stamps: VecDeque::new(),
606	            max,
607	            per,
608	        }
609	    }
610	
611	    fn allow(&mut self, now: Instant) -> bool {
612	        while self.stamps.front().is_some_and(|&t| now - t >= self.per) {
613	            self.stamps.pop_front();
614	        }
615	        if self.stamps.len() >= self.max {
616	            return false;
617	        }
618	        self.stamps.push_back(now);
619	        true
620	    }
621	}
622	
623	struct Limits {
624	    pair: Mutex<RateWindow>,
625	    info: Mutex<RateWindow>,
626	}
627	
628	impl Limits {
629	    /// Whether a request for `path` is over its window; a poisoned lock
630	    /// counts as over, never as open.
631	    fn limited(&self, path: &str) -> bool {
632	        let window = match path {
633	            PAIR_PATH => &self.pair,
634	            INFO_PATH => &self.info,
635	            _ => return false,
636	        };
637	        !window.lock().map_or(true, |mut w| w.allow(Instant::now()))
638	    }
639	}
