642	struct Shared {
643	    tls: Arc<ServerConfig>,
644	    requests: SyncSender<RemoteIncoming>,
645	    frames: SyncSender<SubscriberFrame>,
646	    wake: Arc<dyn Fn() + Send + Sync>,
647	    pools: Pools,
648	    limits: Limits,
649	    next_subscriber: AtomicU64,
650	}
