652	/// The TLS listener: an accept thread, one thread per connection,
653	/// requests handed to the frame over a bounded channel. Bound only by
654	/// the instance that holds the store lock.
655	pub struct RemotePort {
656	    addr: SocketAddr,
657	    requests: Receiver<RemoteIncoming>,
658	    frames: Receiver<SubscriberFrame>,
659	    stop: Arc<AtomicBool>,
660	    thread: Option<JoinHandle<()>>,
661	}
